def transform(grid):
    R, C = len(grid), len(grid[0])

    # The grid is tiled by equal n×n blocks with one-cell gaps.
    n = round((R + 1) ** 0.5)
    if n * n + n - 1 != R or C != R:
        return [[0 if v == 3 else v for v in row] for row in grid]
    pitch = n + 1

    # Find the repeated nonempty tile pattern, ignoring tiles covered by 3.
    counts = {}
    for i in range(n):
        for j in range(n):
            r0, c0 = i * pitch, j * pitch
            if any(grid[r][c] == 3
                   for r in range(r0, r0 + n)
                   for c in range(c0, c0 + n)):
                continue
            pattern = tuple(
                (r, c)
                for r in range(n)
                for c in range(n)
                if grid[r0 + r][c0 + c] == 2
            )
            if pattern:
                counts[pattern] = counts.get(pattern, 0) + 1

    if not counts:
        return [[0 if v == 3 else v for v in row] for row in grid]

    pattern = max(counts, key=lambda p: (counts[p], len(p)))
    cells = set(pattern)
    out = [[0] * C for _ in range(R)]

    # The tile pattern also specifies where its copies belong in the larger grid.
    for i, j in cells:
        r0, c0 = i * pitch, j * pitch
        for dr, dc in cells:
            out[r0 + dr][c0 + dc] = 2
        # Mark the cell corresponding to this copy's position in the pattern.
        out[r0 + i][c0 + j] = 8

    return out
